function se = ElementLaplacianMatrix(nnpe,nqptv,wtq,bigNprime,detj,kmatrix)%% Called by MechMonics and FitFieldDataWithHarmonics%% forms elemental stiffness matrix for solving the negative Laplacian%  over grains of a polycrystal%iend=nnpe;se = zeros(iend,iend);                                       for   k=1:1:nqptv       bigNprimeqp = bigNprime(:,:,k);                                      xkfac(k)=wtq(k)*detj(k);      se = se + xkfac(k)*(bigNprimeqp' * kmatrix' * kmatrix * bigNprimeqp);      end